<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/functions.php';
$u=require_auth();
if(!is_admin($u)) json_response(['error'=>'Acesso restrito ao administrador.'],403);
if(PANEL_UPDATE_MANIFEST_URL==='') json_response(['error'=>'PANEL_UPDATE_MANIFEST_URL não está configurado no .env.'],503);
if(!class_exists('ZipArchive')) json_response(['error'=>'A extensão ZipArchive do PHP não está habilitada.'],500);
function upd_fetch(string $url,string $dest): void { $fp=@fopen($dest,'wb'); if(!$fp) throw new RuntimeException('Não foi possível criar o arquivo temporário.'); $ch=curl_init($url); if(!$ch){fclose($fp);throw new RuntimeException('cURL indisponível.');} curl_setopt_array($ch,[CURLOPT_FILE=>$fp,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_TIMEOUT=>120,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_USERAGENT=>'ConnectPlus-Updater/1']); $ok=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);fclose($fp);if(!$ok||$code<200||$code>=300)throw new RuntimeException('Falha ao baixar atualização'.($err?': '.$err:'')); }
function upd_manifest(): array { $ctx=stream_context_create(['http'=>['timeout'=>10,'header'=>"Accept: application/json\r\nUser-Agent: ConnectPlus-Updater/1\r\n"],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);$raw=@file_get_contents(PANEL_UPDATE_MANIFEST_URL,false,$ctx);if($raw===false)throw new RuntimeException('Falha ao acessar manifesto.');$m=json_decode($raw,true);if(!is_array($m))throw new RuntimeException('Manifesto inválido.');return $m; }
function upd_safe_path(string $p): bool { $p=str_replace('\\','/',$p);if($p===''||str_starts_with($p,'/')||str_contains($p,'../')||preg_match('/^[A-Za-z]:\//',$p))return false;$blocked=['.env','data/','uploads/','update/','logs/'];foreach($blocked as $b){if($p===$b||str_starts_with($p,$b))return false;}return true; }
function upd_backup(array $paths,string $backupRoot): void { foreach($paths as $path){$src=__DIR__.'/../'.$path;if(!is_file($src))continue;$dest=$backupRoot.'/'.$path;@mkdir(dirname($dest),0750,true);if(!@copy($src,$dest))throw new RuntimeException('Falha ao criar backup de '.$path); } }
try{$m=upd_manifest();$version=trim((string)($m['version']??''));$url=trim((string)($m['download_url']??''));$sha=strtolower(trim((string)($m['sha256']??'')));if($version===''||$url===''||!preg_match('/^[a-f0-9]{64}$/',$sha))throw new RuntimeException('Manifesto inválido.');if(version_compare(PANEL_VERSION,$version,'>='))json_response(['message'=>'O painel já está atualizado.','version'=>PANEL_VERSION]);if(!preg_match('~^https://~i',$url))throw new RuntimeException('Download inseguro: use HTTPS.');$tmp=PANEL_UPDATE_DIR.'/update-'.bin2hex(random_bytes(8)).'.zip';upd_fetch($url,$tmp);if(!hash_equals($sha,strtolower(hash_file('sha256',$tmp)))){ @unlink($tmp);throw new RuntimeException('SHA-256 da atualização não confere.'); }
$zip=new ZipArchive();if($zip->open($tmp)!==true){@unlink($tmp);throw new RuntimeException('Não foi possível abrir o pacote.');}$files=[];for($i=0;$i<$zip->numFiles;$i++){ $n=$zip->getNameIndex($i);if($n!==false&&substr($n,-1)!=='/'&&upd_safe_path($n))$files[]=$n;else if($n!==false&&substr($n,-1)!=='/'){$zip->close();@unlink($tmp);throw new RuntimeException('Pacote contém caminho bloqueado: '.$n);} }$backup=PANEL_BACKUP_DIR.'/'.date('Ymd-His').'-'.$version;@mkdir($backup,0750,true);upd_backup($files,$backup);$root=realpath(__DIR__.'/..');foreach($files as $n){$target=$root.'/'.$n;@mkdir(dirname($target),0755,true);$data=$zip->getFromName($n);if($data===false||@file_put_contents($target,$data)===false){$zip->close();throw new RuntimeException('Falha ao instalar '.$n);}}$zip->close();@unlink($tmp);$st=db()->prepare("INSERT INTO logs(user_id,username,action,module,description) VALUES(?,?,?,?,?)");$st->execute([(int)$u['id'],(string)$u['username'],'panel_update','admin','Painel atualizado para a versão '.$version.'. Backup: '.$backup]);json_response(['message'=>'Painel atualizado para a versão '.$version.'. Backup criado antes da atualização.','version'=>$version]);}catch(Throwable $e){if(isset($tmp)&&is_file($tmp))@unlink($tmp);json_response(['error'=>$e->getMessage()],500);}
